import org.openjdk.jmh.annotations.*;
import org.openjdk.jmh.infra.Blackhole;

import java.util.Arrays;
import java.util.Comparator;
import java.util.concurrent.TimeUnit;

@State(Scope.Thread)
@BenchmarkMode(Mode.Throughput)
@OutputTimeUnit(TimeUnit.MICROSECONDS)
@Fork(1)
@Warmup(iterations = 5)
@Measurement(iterations = 5)
public class ArraySorterBenchmark {

    private byte[] byteInput;
    private int[] intInput;
    private Integer[] integerInput;
    private Integer[] integerInputWithComparator;
    private Comparator<Integer> customComparator;

    @Setup
    public void setup() {
        // Setup byte array input
        byteInput = new byte[100];
        for (int i = 0; i < byteInput.length; i++) {
            byteInput[i] = (byte) (127 - i);
        }

        // Setup int array input
        intInput = new int[100];
        for (int i = 0; i < intInput.length; i++) {
            intInput[i] = 100 - i;
        }

        // Setup Integer array input
        integerInput = new Integer[100];
        for (int i = 0; i < integerInput.length; i++) {
            integerInput[i] = 100 - i;
        }

        // Setup array for comparator test
        integerInputWithComparator = Arrays.copyOf(integerInput, integerInput.length);
        customComparator = (a, b) -> b.compareTo(a); // Reverse order comparator
    }

    @Benchmark
    public byte[] sortByte() {
        return ArraySorter.sort(byteInput);
    }

    @Benchmark
    public int[] sortInt() {
        return ArraySorter.sort(intInput);
    }

    @Benchmark
    public Integer[] sortGeneric() {
        return ArraySorter.sort(integerInput);
    }

    @Benchmark
    public Integer[] sortGenericWithComparator() {
        return ArraySorter.sort(integerInputWithComparator, customComparator);
    }
}

