     */
    private static void unregister(final Object lhs, final Object rhs) {
        final Set<Pair<IDKey, IDKey>> registry = getRegistry();
        registry.remove(getRegisterPair(lhs, rhs));
        if (registry.isEmpty()) {
            REGISTRY.remove();
        }
    }

